import json,collections
d=json.load(open('guardrails/language-rules.json'))
def walk(o):
    if isinstance(o,dict):
        if 'armed' in o and 'status' in o: yield o
        for v in o.values(): yield from walk(v)
    elif isinstance(o,list):
        for v in o: yield from walk(v)
c=collections.Counter()
for r in walk(d):
    if r['status'] in ('stated-only','absent'):
        c[(r['status'],tuple(r['armed']) if isinstance(r['armed'],list) else r['armed'])]+=1
for k,v in c.items(): print(k,v)
